package dev.dangeroni.offhandfix.mixin;
import dev.dangeroni.offhandfix.OffhandRefill;import net.minecraft.item.ItemStack;import net.minecraft.network.packet.c2s.play.PlayerActionC2SPacket;import net.minecraft.server.network.ServerPlayNetworkHandler;import net.minecraft.server.network.ServerPlayerEntity;
import org.spongepowered.asm.mixin.Final;import org.spongepowered.asm.mixin.Mixin;import org.spongepowered.asm.mixin.Shadow;import org.spongepowered.asm.mixin.injection.At;import org.spongepowered.asm.mixin.injection.Inject;import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
@Mixin(ServerPlayNetworkHandler.class) abstract class ServerGamePacketListenerImplMixin {@Shadow @Final private ServerPlayerEntity player;
 @Inject(method="onPlayerAction",at=@At("HEAD"),cancellable=true) private void offhandfix$refillOffhandBeforeSwap(PlayerActionC2SPacket packet,CallbackInfo ci){if(packet.getAction()!=PlayerActionC2SPacket.Action.SWAP_ITEM_WITH_OFFHAND)return;ItemStack source=player.getMainHandStack();if(!OffhandRefill.tryRefillOffhand(player,source))return;if(source.isEmpty())player.getInventory().setStack(player.getInventory().selectedSlot,ItemStack.EMPTY);player.getInventory().markDirty();player.playerScreenHandler.sendContentUpdates();player.currentScreenHandler.sendContentUpdates();ci.cancel();}
}
